CREATE TABLE IF NOT EXISTS generation_billing_groups(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),base_url TEXT NOT NULL,credential_hash TEXT NOT NULL,model TEXT NOT NULL,amount REAL NOT NULL,currency TEXT NOT NULL,anchor_run_id TEXT NOT NULL REFERENCES generation_runs(id),evidence TEXT NOT NULL,updated_at TEXT NOT NULL,UNIQUE(project_id,base_url,credential_hash,model));
CREATE TABLE IF NOT EXISTS generation_billing_group_runs(run_id TEXT PRIMARY KEY REFERENCES generation_runs(id),group_id TEXT NOT NULL REFERENCES generation_billing_groups(id));
CREATE VIEW IF NOT EXISTS generation_budget_usage AS SELECT g.*,CASE WHEN b.id IS NOT NULL THEN CASE WHEN b.anchor_run_id=g.id THEN b.amount ELSE 0 END ELSE COALESCE(g.cost,g.reserved) END AS budget_charge FROM generation_runs g LEFT JOIN generation_billing_group_runs m ON m.run_id=g.id LEFT JOIN generation_billing_groups b ON b.id=m.group_id;
